function pm(e) {
  return [...e.awards.map((t) => ({
    idempotencyKey: `expedition:${t.key}`,
    actionId: t.actionId,
    sourceId: t.runId,
    fromAccountId: "counterparty:game:expedition",
    toAccountId: "player",
    amount: t.amount,
    kind: "expedition_award",
    title: rw.name
  })), ...e.purchases.map((t) => ({
    idempotencyKey: `expedition:outfit:${t.id}`,
    actionId: t.actionId,
    sourceId: t.id,
    fromAccountId: "player",
    toAccountId: "system:sink",
    amount: t.amount,
    kind: "expedition_outfit",
    title: rw.wardrobe
  }))];
}
